export interface ConnectorConfig {
  /** Slack bot token for #sales channel (from SLACK_BOT_TOKEN_SALES env var) */
  slackSalesToken: string
  /** Slack bot token for #support channel (from SLACK_BOT_TOKEN_SUPPORT env var) */
  slackSupportToken: string
  /** Slack channel ID for #sales (e.g., C01SALESCHANNELID) */
  slackSalesChannel: string
  /** Slack channel ID for #support (e.g., C01SUPPORTCHANNELID) */
  slackSupportChannel: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface TwilioSmsPayload {
  Body: string
  From: string
  MessageSid: string
}

export interface SlackPostResponse {
  ok: boolean
  channel: string
  ts: string
}

export interface HandleResult {
  routedTo: 'sales' | 'support'
  slackResponse: SlackPostResponse
  messageSid: string
}

const SALES_ROUTE_PATTERN = /pricing|quote|demo/i

function validatePayload(payload: unknown): asserts payload is TwilioSmsPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected object with Body, From, MessageSid')
  }
  const p = payload as Record<string, unknown>
  const missing: string[] = []
  if (typeof p.Body !== 'string') missing.push('Body')
  if (typeof p.From !== 'string') missing.push('From')
  if (typeof p.MessageSid !== 'string') missing.push('MessageSid')
  if (missing.length > 0) {
    throw new Error(`Missing required fields: ${missing.join(', ')}`)
  }
}

async function postToSlack(
  token: string,
  channel: string,
  text: string,
  fetchFn: typeof fetch,
): Promise<SlackPostResponse> {
  const res = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel, text }),
  })

  if (!res.ok) {
    throw new Error(`Slack API error: ${res.status} ${res.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  return res.json() as Promise<SlackPostResponse>
}

export async function handle(
  payload: TwilioSmsPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  validatePayload(payload)

  const { Body, From, MessageSid } = payload
  const fetchFn = config.fetch ?? fetch

  const isSales = SALES_ROUTE_PATTERN.test(Body)
  const target = isSales ? 'sales' : 'support'

  const token = isSales ? config.slackSalesToken : config.slackSupportToken
  const channel = isSales ? config.slackSalesChannel : config.slackSupportChannel

  const slackResponse = await postToSlack(token, channel, Body, fetchFn)

  return {
    routedTo: target,
    slackResponse,
    messageSid: MessageSid,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, TwilioSmsPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.routedTo).toBe('sales')
    expect(result.slackResponse.ok).toBe(true)
    expect(result.messageSid).toBe(SOURCE_EXAMPLE.MessageSid)
  })
})

describe('handle', () => {
  it('routes to sales when body matches pricing keyword', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://slack.com/api/chat.postMessage')
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-sales-token')
      expect(req.json).toEqual({ channel: 'C01SALESCHANNELID', text: 'Need a quote for enterprise' })
      return jsonResponse({ ok: true, channel: 'C01SALESCHANNELID', ts: '1234567890.123' })
    })

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    const payload: TwilioSmsPayload = {
      Body: 'Need a quote for enterprise',
      From: '+15551234567',
      MessageSid: 'SM1234567890',
    }

    const result = await handle(payload, config)
    expect(result.routedTo).toBe('sales')
    expect(result.slackResponse.channel).toBe('C01SALESCHANNELID')
    expect(calls.length).toBe(1)
  })

  it('routes to support when body does not match sales keywords', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-support-token')
      expect(req.json).toEqual({ channel: 'C01SUPPORTCHANNELID', text: 'How do I reset my password?' })
      return jsonResponse({ ok: true, channel: 'C01SUPPORTCHANNELID', ts: '1234567890.456' })
    })

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    const payload: TwilioSmsPayload = {
      Body: 'How do I reset my password?',
      From: '+15551234567',
      MessageSid: 'SM1234567891',
    }

    const result = await handle(payload, config)
    expect(result.routedTo).toBe('support')
    expect(result.slackResponse.channel).toBe('C01SUPPORTCHANNELID')
    expect(calls.length).toBe(1)
  })

  it('uses correct auth header and channel for each target', async () => {
    const salesCalls: RecordedCall[] = []
    const supportCalls: RecordedCall[] = []

    const { fetch: salesFetch } = fakeFetch((req: RecordedCall) => {
      salesCalls.push(req)
      return jsonResponse({ ok: true, channel: 'C01SALESCHANNELID', ts: '1' })
    })
    const { fetch: supportFetch } = fakeFetch((req: RecordedCall) => {
      supportCalls.push(req)
      return jsonResponse({ ok: true, channel: 'C01SUPPORTCHANNELID', ts: '2' })
    })

    const baseConfig: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
    }

    await handle(
      { Body: 'demo request', From: '+1', MessageSid: 'SM1' },
      { ...baseConfig, fetch: salesFetch },
    )
    await handle(
      { Body: 'support question', From: '+2', MessageSid: 'SM2' },
      { ...baseConfig, fetch: supportFetch },
    )

    expect(salesCalls[0].headers.get('authorization')).toBe('Bearer xoxb-sales-token')
    expect(salesCalls[0].json).toEqual({ channel: 'C01SALESCHANNELID', text: 'demo request' })
    expect(supportCalls[0].headers.get('authorization')).toBe('Bearer xoxb-support-token')
    expect(supportCalls[0].json).toEqual({ channel: 'C01SUPPORTCHANNELID', text: 'support question' })
  })

  it('maps Body to text, From to sender context, MessageSid to result id', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.json).toEqual({ channel: 'C01SALESCHANNELID', text: 'Interested in pricing' })
      return jsonResponse({ ok: true, channel: 'C01SALESCHANNELID', ts: '999' })
    })

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    const payload: TwilioSmsPayload = {
      Body: 'Interested in pricing',
      From: '+15559876543',
      MessageSid: 'SM9999999999',
    }

    const result = await handle(payload, config)
    expect(result.messageSid).toBe('SM9999999999')
    expect(result.slackResponse.ts).toBe('999')
    expect(calls[0].json).toEqual({ channel: 'C01SALESCHANNELID', text: 'Interested in pricing' })
  })

  it('throws descriptive error when Body is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
