    await expect(handle(payload, config)).rejects.toThrowError('Missing required fields: MessageSid')
  })

  it('throws error with status and endpoint on non-2xx Slack response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    const payload: TwilioSmsPayload = {
      Body: 'pricing inquiry',
      From: '+15551234567',
      MessageSid: 'SM123',
    }

    await expect(handle(payload, config)).rejects.toThrowError(
      'Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage',
    )
    expect(calls.length).toBe(1)
  })

  it('throws error on 500 response from Slack', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'internal_error' }, 500))

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    const payload: TwilioSmsPayload = {
      Body: 'demo request',
      From: '+15551234567',
      MessageSid: 'SM123',
    }

    await expect(handle(payload, config)).rejects.toThrowError(
      'Slack API error: 500 Internal Server Error at POST https://slack.com/api/chat.postMessage',
    )
  })

  it('case-insensitive regex matches PRICING, QUOTE, DEMO', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.headers.get('authorization')).toBe('Bearer xoxb-sales-token')
      return jsonResponse({ ok: true, channel: 'C01SALESCHANNELID', ts: '1' })
    })

    const config: ConnectorConfig = {
      slackSalesToken: 'xoxb-sales-token',
      slackSupportToken: 'xoxb-support-token',
      slackSalesChannel: 'C01SALESCHANNELID',
      slackSupportChannel: 'C01SUPPORTCHANNELID',
      fetch,
    }

    for (const body of ['PRICING info', 'Quote please', 'DEMO request', 'PrIcInG']) {
      calls.length = 0
      const result = await handle({ Body: body, From: '+1', MessageSid: 'SM1' }, config)
      expect(result.routedTo).toBe('sales')
      expect(calls.length).toBe(1)
    }
  })
})

